import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './Auth.css'; // Fichier CSS partagé pour les pages d'authentification

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');

    try {
      const user = login(email, password, role);
      
      // Redirect based on role
      switch (user.role) {
        case 'admin':
          navigate('/admin');
          break;
        case 'professor':
          navigate('/professor');
          break;
        case 'student':
          navigate('/student');
          break;
        default:
          navigate('/');
      }
    } catch (error) {
      setError('Erreur de connexion. Veuillez vérifier vos informations.');
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-layout">
        {/* Left panel */}
        <div className="auth-sidebar">
          <div className="auth-logo">
            <img src=".\src\pages\Login.jsx" alt="QGen Logo" className="logo-img" />
            <h1>QGen</h1>
          </div>
          <div className="auth-slogan">
            <h2>Un sujet, un quiz.<br/>C'est tout!</h2>
            <p className="auth-subtitle">Votre assistant pour créer des quiz simples, rapides et efficaces.</p>
          </div>
        </div>

        {/* Right panel */}
        <div className="auth-content">
          <div className="auth-welcome">
            <h1>BIENVENUE</h1>
          </div>
          <div className="auth-form-container">
            <h2 className="auth-form-title">CONNEXION</h2>
            
            {error && <div className="error-message">{error}</div>}
            
            <form onSubmit={handleSubmit} className="auth-form">
              <div className="form-group">
                <div className="input-icon">
                  <i className="email-icon">✉️</i>
                  <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    className="auth-input"
                  />
                </div>
              </div>
              
              <div className="form-group">
                <div className="input-icon">
                  <i className="password-icon">🔒</i>
                  <input
                    type="password"
                    placeholder="Mot de passe"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    className="auth-input"
                  />
                </div>
              </div>
              
              <div className="form-group">
                <select
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                  className="auth-select"
                >
                  <option value="student">Étudiant</option>
                  <option value="professor">Professeur</option>
                  <option value="admin">Administrateur</option>
                </select>
              </div>
              
              <button type="submit" className="auth-button">Se connecter</button>
            </form>
            
            <div className="auth-alternative">
              <p>Continuer avec:</p>
              <button className="social-login-button">
                <img src="/api/placeholder/20/20" alt="Google" /> Continuer avec Google
              </button>
            </div>
            
            <div className="auth-links">
              <Link to="/register" className="register-link">S'inscrire</Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
